function update(dt) {
  if (input.wasPressed('r')) {
    player.reset();
    clearPlayerPosition();
  }
  if (input.wasPressed('m')) overmap.toggle();
  if (input.wasPressed('l')) lighting.togglePause();
  lighting.update(dt);
  player.update(input, dt);
  chunks.streamAround(player.x, player.y);
  if ((frame & 31) === 0) savePlayerPosition(player);
}

function loop(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  update(dt);
  renderer.draw(chunks, player, lighting);
  if ((frame++ & 7) === 0) {
    renderer.hud(chunks, player, lighting);
    overmap.draw();
  }
  input.endFrame();
  requestAnimationFrame(loop);
}

